"""Magnetic Force Between Two Balls — binary search on the minimum gap.

Greedily place balls as early as the candidate gap allows; if all m fit, the gap
is achievable, so search for the largest such gap.

Time: O(n log n + n log range)   Space: O(1)
"""
from typing import List


class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position.sort()

        def fits(gap: int) -> bool:
            placed, last = 1, position[0]
            for spot in position[1:]:
                if spot - last >= gap:
                    placed += 1
                    last = spot
                    if placed == m:
                        return True
            return placed >= m

        lo, hi, best = 1, position[-1] - position[0], 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if fits(mid):
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return best
